package com.nettel.maritimo.next.ui;
import android.Manifest;import android.content.Intent;import android.content.pm.PackageManager;import android.os.*;import android.widget.*;import androidx.core.app.ActivityCompat;import com.nettel.maritimo.next.data.SessionStore;
public class MainActivity extends BaseActivity {@Override protected void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=33&&ActivityCompat.checkSelfPermission(this,Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)ActivityCompat.requestPermissions(this,new String[]{Manifest.permission.POST_NOTIFICATIONS},10);LinearLayout r=Ui.page(this,"Nettel Marítimo");LinearLayout g=new LinearLayout(this);g.setOrientation(LinearLayout.VERTICAL);Ui.pad(g,20);TextView hello=new TextView(this);hello.setText("Bienvenido, "+new SessionStore(this).user());hello.setTextSize(20);g.addView(hello);add(g,"Dispositivos",DevicesActivity.class);add(g,"Mapa de flota",MapActivity.class);add(g,"Histórico de posiciones",HistoryActivity.class);add(g,"Alertas",AlertsActivity.class);add(g,"Usuarios",UsersActivity.class);add(g,"Configuración",SettingsActivity.class);r.addView(g);setContentView(r);}private void add(LinearLayout g,String text,Class<?>c){android.view.View b=Ui.button(this,text);g.addView(b,new LinearLayout.LayoutParams(-1,Ui.dp(this,58)));b.setOnClickListener(v->startActivity(new Intent(this,c)));}}
